export const RIVET_FEATURE_FLAG_USER_KEY_HEADER =
  'x-rivet-feature-flag-user-key';

type ConfigFeatureFlagUserKeyParams = {
  headers: Record<string, string | string[] | undefined>;
  fallbackEmail?: string;
};

const normalizeUserKey = (value: string | undefined): string | undefined => {
  const trimmedValue = value?.trim();
  return trimmedValue && trimmedValue.length > 0 ? trimmedValue : undefined;
};

const getHeaderValue = (
  value: string | string[] | undefined,
): string | undefined => {
  if (Array.isArray(value)) {
    return value[0];
  }
  return value;
};

export const getConfigFeatureFlagUserKey = ({
  headers,
  fallbackEmail,
}: ConfigFeatureFlagUserKeyParams): string | undefined =>
  normalizeUserKey(getHeaderValue(headers[RIVET_FEATURE_FLAG_USER_KEY_HEADER])) ??
  normalizeUserKey(fallbackEmail);
